module freq_div (
	input CLK_in, RST,
	output reg CLK_50, CLK_10, CLK_1
);
	reg [3:0] cnt_10;
	reg [6:0] cnt_100;


	//CLK_50
	always@(posedge CLK_in or posedge RST) begin
		if(RST)
			CLK_50 <= 0;
		else
			CLK_50 <= ~CLK_50;
	end

	//CLK_10
	always@(posedge CLK_in or posedge RST) begin
		if(RST) begin
			cnt_10 <= 0;
			CLK_10 <= 0;
		end

		else if(cnt_10 == 4'd4) begin
			cnt_10 <= 0;
			CLK_10 <= ~CLK_10;
		end

		else
			cnt_10 <= cnt_10 + 1;
	end

	//CLK_1
	always@(posedge CLK_in or posedge RST) begin
		if(RST) begin
			cnt_100 <= 0;
			CLK_1 <= 0;
		end

		else if(cnt_100 == 7'd49) begin
			cnt_100 <= 0;
			CLK_1 <= ~CLK_1;
		end

		else
			cnt_100 <= cnt_100 + 1;
	end
endmodule
